data.query:
query GetShipment($where: ShipmentWhereInput!) {
  shipment(where: $where) {
    total
    edges {
      node {
        id
        number
        active
        shipAt
        shipmentType { id name }
        shipmentLines {
          edges {
            node {
              id
              number
              quantity { value unitId }
              inventories {
                edges {
                  node {
                    id
                    serialNumber
                    active
                    inventoryStatusId
                    mrbHoldStatus
                    mrbCaseId
                    storageUnit { id code }
                    quantity { value unitId }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.responseTransform:
{
  "success": false,
  "severity": "error",
  "title": "Shipment Not Found",
  "message": "No shipment record found for the provided ID.",
  "data": { "shipmentId": $state.context.INPUT.shipmentId }
}

{
  "success": false,
  "severity": "warning",
  "title": "Return Already Completed",
  "message": "This return shipment has already been completed.",
  "data": {
    "shipmentNumber": $state.context.SHIPMENT.number,
    "completedAt": $state.context.SHIPMENT.shipAt
  }
}

data.mutation:
mutation CompleteReturn(
  $shipmentPayload: [ShipmentUpdatePayloadInput!]!
  $inventoryPayload: [InventoryUpdatePayloadInput!]!
) {
  updateShipment(payload: $shipmentPayload) {
    id
    number
    shipAt
  }
  updateInventory(payload: $inventoryPayload) {
    id
    serialNumber
    inventoryStatusId
    mrbHoldStatus
    mrbCaseId
  }
}

data.responseTransform:
{
  "success": true,
  "severity": "success",
  "title": "Return Complete",
  "message": "Return shipment completed. All inventory retired.",
  "data": {
    "shipmentNumber": $state.context.SHIPMENT.number,
    "inventoryCount": $count($state.context.INVENTORIES)
  }
}

{
  "success": true,
  "severity": "success",
  "title": "MRB Return Complete",
  "message": "Return shipment completed and MRB hold cleared. Update the RTV action item in QCS to close the disposition. Case ID: " & $state.context.MRB_CASE_ID,
  "data": {
    "shipmentNumber": $state.context.SHIPMENT.number,
    "mrbCaseId": $state.context.MRB_CASE_ID,
    "inventoryReturned": $count($state.context.INVENTORIES)
  }
}

